<?php $related=array_values(array_filter(tripCatalog(),fn($x)=>$x['city']===$item['city']&&$x['id']!==$item['id']));usort($related,fn($a,$b)=>(int)($b['type']===$item['type'])<=>(int)($a['type']===$item['type']));if($related):?>
<section class="market-related"><h2><?=$label('עוד חוויות ביעד','More experiences in this destination','Другие впечатления в этом городе')?></h2><div class="market-related-grid"><?php foreach(array_slice($related,0,4) as $r):?><article><a href="<?=e($r['url'])?>"><img src="<?=e($r['image'])?>" width="400" height="270" loading="lazy" alt=""><h3><?=e($r['title'])?></h3></a><p><?=e($r['duration'])?></p><?php $community=communityRatingAllowed($r)?communityRatingSummary($r['id']):['count'=>0];if($community['count']):?><small class="market-stars">★ <bdi><?=number_format((float)$community['average'],1)?> / 5</bdi> · Tripovela</small><?php endif?><strong><?=e($r['cost']==='free'?languagePhrase('חינם','Free','Бесплатно'):($r['price']?languagePhrase('החל מ־','From ','От ').$r['price']:languagePhrase('בדיקת מחיר','Check price','Уточнить цену')))?></strong><?=tripSaveButton($r)?><small class="market-muted"><?=e($r['credit']??'')?></small></article><?php endforeach?></div></section><?php endif?>